--------------------------------------------------------------------------------
-- CargoVerse — Smart Warehouse reference data (GENERATED by server/db/gen-wms-seed.ts — do not edit)
-- Racks, bins and the aisle graph of each building, product handling rules, sensors,
-- 90 days of demand history (dates relative to today) and sample damage reports.
-- Lots and bin contents are created from the current inventory when the server first starts.
--------------------------------------------------------------------------------
SET DEFINE OFF

-- the cold-chain product (databases created before it existed get it here)
MERGE INTO skus d USING (SELECT 'MED-INS' AS sku_id FROM dual) s ON (d.sku_id = s.sku_id)
WHEN NOT MATCHED THEN INSERT (sku_id, name, category, units_per_pallet, kg_per_pallet, pallet_look, icon)
VALUES ('MED-INS', 'Insulin Pens (2–8 °C)', 'Pharma', 480, 150, 'white', 'medical');
MERGE INTO inventory d USING (SELECT 'WH-04' AS facility_id, 'MED-INS' AS sku_id FROM dual) s
   ON (d.facility_id = s.facility_id AND d.sku_id = s.sku_id)
WHEN NOT MATCHED THEN INSERT (facility_id, sku_id, units, reorder_level, display_order) VALUES ('WH-04', 'MED-INS', 2880, 960, 5);
MERGE INTO store_stock d USING (SELECT 'ST-02' AS store_id, 'MED-INS' AS sku_id FROM dual) s
   ON (d.store_id = s.store_id AND d.sku_id = s.sku_id)
WHEN NOT MATCHED THEN INSERT (store_id, sku_id, units, reorder_at, max_units, sales_per_hour, sold_today) VALUES ('ST-02', 'MED-INS', 84, 40, 120, 22, 0);

